/**
 * Names for evidence files. Generated by the app only, from `[a-z0-9-]` and a hash: the
 * title and URL are page-chosen text, and must never reach a path as anything else.
 *
 * No electron import.
 */
import { slugify } from '../../../osint/utils/slug'

/**
 * A filename that says what it is, without inviting a path traversal or a 300-char name.
 * No accent folding, unlike the Sources notes' slug: existing evidence keeps its name.
 */
export function evidenceSlug(title: string, url: string): string {
	const source = (title || '').trim() || (() => {
		try { return new URL(url).hostname }
		catch { return 'capture' }
	})()
	return slugify(source) || 'capture'
}

/**
 * The stem every file of one capture shares: the slug plus the first 8 hex digits of the
 * archive's sha256. Two captures of one page (same title, same URL) get different names
 * because their archives differ; the same archive twice gets the same name, which is the
 * one case where it is the same evidence.
 */
export function evidenceStem(title: string, url: string, sha256Hex: string): string {
	if (!/^[0-9a-f]{64}$/.test(sha256Hex)) throw new Error('evidenceStem needs a lowercase hex sha256')
	return `${evidenceSlug(title, url)}-${sha256Hex.slice(0, 8)}`
}
